const a="b15d84c82f7d",e="vertaler + keurder (claude-opus-5-5)",n="2026-10-20",o=[{personId:"B",after:[],nudge:"Comincia da Bruno. Si trovava proprio accanto a un tavolo. Cerca il tavolo e guarda quali caselle proprio lì accanto sono libere.",reasoning:"Il tavolo è in riga 4, colonna 4. Alla sua sinistra, in riga 4, colonna 3, c'è una libreria, e lì non può stare nessuno. Proprio accanto al tavolo resta una sola casella.",answer:"Bruno si trova in riga 3, colonna 4, nella casella subito sopra il tavolo. Sull'altra casella proprio accanto al tavolo c'è una libreria."},{personId:"A",after:["B"],nudge:"Guarda Anna. Si trovava nella 2ª colonna. Quali caselle della colonna 2 sono ancora possibili?",reasoning:"In riga 1, colonna 2 c'è un armadio e in riga 4, colonna 2 una libreria: lì non può stare nessuno. Ogni riga contiene esattamente una persona, e la riga 3 è già occupata da Bruno. Nella colonna 2 resta una sola casella.",answer:"Anna si trova in riga 2, colonna 2. Nella colonna 2 ci sono un armadio (riga 1) e una libreria (riga 4), e la riga 3 è occupata da Bruno."},{personId:"C",after:["B","A"],nudge:"Guarda Cecilia. Si trovava presso una finestra. Cerca le finestre sulla mappa.",reasoning:"Ci sono finestre presso tre caselle: riga 1, colonna 3; riga 3, colonna 1; e riga 4, colonna 4. In riga 4, colonna 4 c'è un tavolo, e la riga 3 è già occupata da Bruno. Quale finestra resta?",answer:"Cecilia si trova in riga 1, colonna 3, presso la finestra in alto. La finestra nella riga 3 è esclusa a causa di Bruno, e presso la finestra nella riga 4 c'è un tavolo."},{personId:"V",after:["B","A","C"],nudge:"Vanna è la vittima e non ha una scheda. Guarda quale riga e quale colonna sono ancora vuote.",reasoning:"Ogni riga e ogni colonna contiene esattamente una persona. Bruno, Anna e Cecilia occupano già le righe 3, 2 e 1 e le colonne 4, 2 e 3. Restano vuote solo la riga 4 e la colonna 1.",answer:"Vanna si trova in riga 4, colonna 1. È l'unica riga e l'unica colonna in cui non c'è ancora nessuno."}],i="Vanna si trovava in cantina. Bruno è l'unico sospettato lì (Anna e Cecilia erano nello studio), quindi il colpevole è Bruno.",l={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},r={source:a,model:e,date:n,steps:o,murderer:i,review:l},s="850dbab4bf0c",c="vertaler (claude-opus-5-5)",t="2026-10-20",d=[{personId:"C",after:[],nudge:"Comincia da Cecilia. Si trovava nella riga più in basso. Quali caselle della riga 4 sono libere?",reasoning:"La riga più in basso è la riga 4. Nelle colonne 2, 3 e 4 di quella riga ci sono dei tavoli, e lì non può stare nessuno. Resta una sola casella.",answer:"Cecilia si trova in riga 4, colonna 1. Le altre caselle della riga 4 sono coperte da tavoli."},{personId:"A",after:["C"],nudge:"Guarda Antonio. Si trovava vicino a una finestra. Cerca le finestre sulla mappa.",reasoning:"Ci sono finestre vicino a tre caselle: riga 1, colonna 1; riga 1, colonna 3; e riga 4, colonna 1. Ogni colonna contiene esattamente una persona, e la colonna 1 è già occupata da Cecilia. Quale finestra resta?",answer:"Antonio si trova in riga 1, colonna 3, vicino alla finestra in alto. Le altre finestre sono nella colonna 1, che è occupata da Cecilia."},{personId:"B",after:["C","A"],nudge:"Guarda Barbara. Era nella 2ª colonna. Quali caselle della colonna 2 sono ancora possibili?",reasoning:"La riga 1 è occupata da Antonio e la riga 4 da Cecilia. In riga 2, colonna 2 c'è un armadio, e lì non può stare nessuno. Nella colonna 2 resta una sola casella.",answer:"Barbara si trova in riga 3, colonna 2. Le righe 1 e 4 sono occupate, e in riga 2, colonna 2 c'è un armadio."},{personId:"V",after:["C","A","B"],nudge:"Valentino è la vittima e non ha una scheda. Guarda quale riga e quale colonna sono ancora vuote.",reasoning:"Ogni riga e ogni colonna contiene esattamente una persona. Cecilia, Antonio e Barbara occupano già le righe 4, 1 e 3 e le colonne 1, 3 e 2. Restano vuote solo la riga 2 e la colonna 4.",answer:"Valentino si trova in riga 2, colonna 4. È l'unica riga e l'unica colonna in cui non c'è ancora nessuno."}],u="Valentino si trovava nello studio. Antonio è l'unico sospettato lì (Barbara e Cecilia erano in cantina), quindi il colpevole è Antonio.",g={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},p={source:s,model:c,date:t,steps:d,murderer:u,review:g},v="0e590a513929",m="vertaler (claude-opus-5-5)",b="2026-10-20",C=[{personId:"C",after:[],nudge:"Comincia da Claudio. La sua scheda dice che si trovava su una sedia. Cerca la sedia sulla mappa.",reasoning:"Claudio si trovava su una sedia. C'è una sola sedia, nello studio. È lì che deve trovarsi Claudio.",answer:"Claudio si trova in riga 4, colonna 1. Lì c'è l'unica sedia, e la sua scheda dice che si trovava su una sedia."},{personId:"A",after:["C"],nudge:"Guarda Alice. Si trovava nella riga più in alto. Quali caselle della riga 1 sono ancora possibili?",reasoning:"In riga 1, colonna 2 c'è un pianoforte e in riga 1, colonna 3 una pianta: lì non può stare nessuno. Ogni colonna contiene esattamente una persona, e la colonna 1 è già occupata da Claudio. Nella riga 1 resta una sola casella.",answer:"Alice si trova in riga 1, colonna 4. Nella riga 1 ci sono un pianoforte (colonna 2) e una pianta (colonna 3), e la colonna 1 è occupata da Claudio."},{personId:"B",after:["C","A"],nudge:"Guarda Bruna. Si trovava nella 2ª colonna. Quali caselle della colonna 2 sono ancora possibili?",reasoning:"Nelle righe 1 e 2 della colonna 2 c'è un pianoforte, e lì non può stare nessuno. La riga 4 è già occupata da Claudio. Nella colonna 2 resta una sola casella.",answer:"Bruna si trova in riga 3, colonna 2. In cima alla colonna 2 c'è un pianoforte, e la riga 4 è occupata da Claudio."},{personId:"V",after:["C","A","B"],nudge:"Vito è la vittima e non ha una scheda. Guarda quale riga e quale colonna sono ancora vuote.",reasoning:"Ogni riga e ogni colonna contiene esattamente una persona. Claudio, Alice e Bruna occupano già le righe 4, 1 e 3 e le colonne 1, 4 e 2. Restano vuote solo la riga 2 e la colonna 3.",answer:"Vito si trova in riga 2, colonna 3. È l'unica riga e l'unica colonna in cui non c'è ancora nessuno."}],h="Vito si trovava nel boudoir. Alice è l'unica sospettata lì (Bruna e Claudio erano nello studio), quindi la colpevole è Alice.",A={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},q={source:v,model:m,date:b,steps:C,murderer:h,review:A},B="f5f4c3de566b",D="vertaler (claude-opus-5-5)",f="2026-10-20",E=[{personId:"D",after:[],nudge:"Comincia da Diego. La sua scheda nomina un oggetto. Quanti oggetti di quel tipo ci sono sulla mappa?",reasoning:"Diego si trovava su una sedia. Guarda la pianta: c'è una sola sedia, nello studio. In quale casella si trova quella sedia?",answer:"Diego si trova in riga 5, colonna 2. Lì c'è l'unica sedia della casa, e la sua scheda dice che si trovava su una sedia."},{personId:"C",after:["D"],nudge:"Guarda Carlo e i due armadi. Quali caselle sono accanto a un armadio, e quali sono escluse dalle schede di Alessia e Biagio?",reasoning:"Carlo si trovava accanto a un armadio, nella stessa stanza. Accanto all'armadio della camera da letto ci sono tre caselle: riga 1, colonna 4; riga 2, colonna 5; e riga 3, colonna 4. Accanto all'armadio della cantina ci sono riga 4, colonna 5 e riga 5, colonna 4. La colonna 5 spetta ad Alessia (colonna più a destra), la riga 3 spetta a Biagio e la riga 5 è occupata da Diego. Quale casella resta?",answer:"Carlo si trova in riga 1, colonna 4. Le altre caselle accanto a un armadio sono escluse: la colonna 5 spetta ad Alessia, la riga 3 a Biagio e la riga 5 è occupata da Diego."},{personId:"B",after:["D","C"],nudge:"Biagio era nella riga 3. Passa in rassegna le caselle di quella riga: quali sono bloccate o escluse per via di una colonna?",reasoning:"Biagio era nella riga 3. In riga 3, colonna 3 c'è il pianoforte, e lì non può stare nessuno. La colonna 2 è occupata da Diego e la colonna 4 da Carlo. La colonna 5 spetta ad Alessia, perché lei si trovava nella colonna più a destra. Quale casella della riga 3 resta?",answer:"Biagio si trova in riga 3, colonna 1. Nella colonna 3 c'è il pianoforte, le colonne 2 e 4 sono occupate da Diego e Carlo, e la colonna 5 spetta ad Alessia."},{personId:"V",after:["D","C","B"],nudge:"Ora la vittima, Vito. Quali righe e colonne sono ancora libere, e quale colonna spetta già ad Alessia?",reasoning:"Le righe 1, 3 e 5 sono occupate, come le colonne 1, 2 e 4. Restano le righe 2 e 4 e le colonne 3 e 5. La colonna 5 spetta ad Alessia, quindi Vito deve essere nella colonna 3. In riga 2, colonna 3 c'è il pianoforte. Dove può trovarsi allora Vito?",answer:"Vito si trova in riga 4, colonna 3. La colonna 5 spetta ad Alessia, quindi lui deve essere nella colonna 3, e in riga 2, colonna 3 c'è il pianoforte."},{personId:"A",after:["D","C","B","V"],nudge:"Alessia è l'ultima che non è ancora sulla mappa. Cosa dice la sua scheda, e quale riga è ancora libera?",reasoning:"Alessia si trovava nella colonna più a destra, cioè nella colonna 5. Le righe 1, 3, 4 e 5 sono già occupate. Quale casella della colonna 5 resta allora?",answer:"Alessia si trova in riga 2, colonna 5. La sua scheda dice la colonna più a destra, e le righe 1, 3, 4 e 5 sono già occupate."}],L="Vito giace nello studio, e Diego è l'unico sospettato che si trovava anche lui nello studio. Il colpevole è quindi Diego.",I={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},w={source:B,model:D,date:f,steps:E,murderer:L,review:I},V="144a6a6f16d9",F="vertaler (claude-opus-5-5)",Q="2026-10-20",z=[{personId:"B",after:[],nudge:"Comincia da Bernardo, nella riga più in alto. Quali caselle sono bloccate lì, e cosa dice la scheda di Antonio sulla cantina?",reasoning:"Bernardo era nella riga 1. In riga 1, colonna 1 c'è un armadio, e lì non può stare nessuno. Le colonne 3, 4 e 5 della riga 1 fanno parte della cantina, e Antonio era l'unica persona in cantina. Quindi Bernardo non può essere lì. Quale casella della riga 1 resta?",answer:"Bernardo si trova in riga 1, colonna 2. Nella colonna 1 c'è un armadio, e le colonne dalla 3 alla 5 fanno parte della cantina, dove c'era solo Antonio."},{personId:"D",after:["B"],nudge:"Guarda Daniela e le sedie. Quali caselle sono proprio accanto a una sedia nella stessa stanza, fuori dalla cantina?",reasoning:"Daniela si trovava proprio accanto a una sedia, nella stessa stanza. Due sedie sono in cantina, ma lì c'era solo Antonio. Le altre due sono in serra, in riga 4, colonna 2 e in riga 5, colonna 1. Accanto a queste ci sono tre caselle: riga 3, colonna 2; riga 5, colonna 2; e riga 4, colonna 1. La colonna 2 è occupata da Bernardo. Quale casella resta?",answer:"Daniela si trova in riga 4, colonna 1, proprio accanto alle sedie della serra. La cantina è di Antonio, e le righe 3 e 5 della colonna 2 sono escluse perché Bernardo occupa la colonna 2."},{personId:"C",after:["B","D"],nudge:"Cecilia si trovava su un letto. Quante caselle occupa il letto, e quale riga è già occupata?",reasoning:"C'è un solo letto, in biblioteca, nelle righe 3 e 4 della colonna 5. La riga 4 è occupata da Daniela. Su quale casella del letto può trovarsi ancora Cecilia?",answer:"Cecilia si trova in riga 3, colonna 5. Il letto occupa le righe 3 e 4 della colonna 5, e la riga 4 è occupata da Daniela."},{personId:"V",after:["B","D","C"],nudge:"Ora la vittima, Valeria. Quali righe sono ancora libere, e in quale di queste deve andare Antonio?",reasoning:"Le righe 1, 3 e 4 sono occupate, quindi restano le righe 2 e 5. Antonio era in cantina, che occupa solo le righe 1 e 2; la riga 1 è di Bernardo, quindi Antonio va nella riga 2. Valeria deve allora essere nella riga 5. Le colonne 1, 2 e 5 sono occupate, e in riga 5, colonna 3 c'è il tavolo. Dove può trovarsi allora Valeria?",answer:"Valeria si trova in riga 5, colonna 4. La riga 2 spetta ad Antonio (cantina), le colonne 1, 2 e 5 sono occupate, e in riga 5, colonna 3 c'è il tavolo."},{personId:"A",after:["B","D","C","V"],nudge:"Antonio è l'ultimo che non è ancora sulla mappa. Cosa dice la sua scheda, e quale riga e quale colonna sono ancora libere?",reasoning:"Antonio era in cantina, nella riga 1 o nella riga 2. La riga 1 è occupata da Bernardo. La colonna 4 è occupata da Valeria e la colonna 5 da Cecilia. Quale casella della cantina resta?",answer:"Antonio si trova in riga 2, colonna 3, in cantina. La riga 1 è occupata da Bernardo, la colonna 4 da Valeria e la colonna 5 da Cecilia."}],$="Valeria giace in biblioteca, e Cecilia è l'unica sospettata che si trovava anche lei in biblioteca. La colpevole è quindi Cecilia.",G={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},_={source:V,model:F,date:Q,steps:z,murderer:$,review:G},N="dfa59a49f03b",S="vertaler + keurder (claude-opus-5-5)",k="2026-10-20",P=[{personId:"A",after:[],nudge:"Comincia da Alice. Cerca la libreria sulla mappa e guarda quali caselle accanto a essa sono libere.",reasoning:"Alice si trovava accanto a una libreria. C'è una sola libreria: in riga 5, colonna 3, in salotto. In riga 4, colonna 3 c'è una pianta, e la casella in riga 5, colonna 2 è dietro un muro, nell'atrio (e lì c'è anche una pianta). Quale casella accanto alla libreria resta?",answer:"Alice si trova in riga 5, colonna 4, accanto alla libreria. In riga 4, colonna 3 c'è una pianta e la casella in riga 5, colonna 2 è dietro un muro, nell'atrio."},{personId:"C",after:["A"],nudge:"Ora Carlo, nella riga 4. Confronta la sua scheda con quella di Bruno, e guarda anche Alice.",reasoning:"Carlo era nella riga 4. Le colonne 1 e 2 della riga 4 fanno parte dell'atrio, e Bruno era da solo nell'atrio, quindi Carlo non può essere lì. In riga 4, colonna 3 c'è una pianta e la colonna 4 è occupata da Alice. Quale casella della riga 4 resta?",answer:"Carlo si trova in riga 4, colonna 5. Le colonne 1 e 2 della riga 4 sono nell'atrio, dove Bruno era da solo, nella colonna 3 c'è una pianta e la colonna 4 è occupata da Alice."},{personId:"D",after:["A","C"],nudge:"Guarda Daniela e la colonna 2. Quali caselle sono escluse dalla scheda di Bruno?",reasoning:"Daniela era nella colonna 2. Le righe 3, 4 e 5 della colonna 2 fanno parte dell'atrio, dove Bruno era da solo; lì Daniela non può essere. In riga 1, colonna 2 c'è un armadio, e lì non può stare nessuno. Quale casella della colonna 2 resta allora?",answer:"Daniela si trova in riga 2, colonna 2. Le righe dalla 3 alla 5 della colonna 2 sono nell'atrio, dove Bruno era da solo, e in riga 1, colonna 2 c'è un armadio."},{personId:"B",after:["A","C","D"],nudge:"Bruno era nell'atrio. Quali righe e colonne dell'atrio sono ancora libere?",reasoning:"L'atrio occupa le righe 3, 4 e 5 delle colonne 1 e 2. La riga 4 è occupata da Carlo, la riga 5 da Alice e la colonna 2 da Daniela. Quale casella dell'atrio resta allora a Bruno?",answer:"Bruno si trova in riga 3, colonna 1. Nell'atrio la riga 4 (Carlo), la riga 5 (Alice) e la colonna 2 (Daniela) sono già occupate."},{personId:"V",after:["A","C","D","B"],nudge:"Vincenzo è l'ultimo che non è ancora sulla mappa. Quale riga e quale colonna sono ancora libere?",reasoning:"Tutti i sospettati sono già sulla mappa. La riga 1 è l'unica riga libera e la colonna 3 l'unica colonna libera. Dove si incrociano?",answer:"Vincenzo si trova in riga 1, colonna 3. La riga 1 e la colonna 3 sono l'unica riga e l'unica colonna in cui non c'è ancora nessuno."}],j="Vincenzo giace nel corridoio. Daniela è l'unica sospettata nel corridoio, quindi la colpevole è Daniela.",O={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},R={source:N,model:S,date:k,steps:P,murderer:j,review:O},T="74a91d976380",x="vertaler + keurder (claude-opus-5-5)",M="2026-10-20",y=[{personId:"C",after:[],nudge:"Comincia da Cecilia. Combina la sua scheda con quella di Davide: quale donna può trovarsi nella stanza di Davide? Poi guarda le stanze nella metà superiore.",reasoning:"Cecilia è l'unica donna, quindi secondo la scheda di Davide Cecilia si trova nella stessa stanza di Davide. Cecilia è nella metà superiore, ma non nella riga 1: quella riga spetta ad Alberto (la sua scheda: riga più in alto). In cantina resta allora solo la riga 2, e lo stesso vale in salotto, perché lì nella riga 3 c'è un tavolo. Cecilia e Davide non possono stare entrambi in una sola riga. In camera da letto Bruno, Cecilia e Davide dovrebbero stare tutti nelle righe 2 e 3, e sono solo due righe. Quale stanza resta allora, e quale casella libera ha nella metà superiore?",answer:"Cecilia si trova in riga 3, colonna 2. Solo nel boudoir c'è posto per Cecilia e Davide insieme, e l'unica casella libera del boudoir nella metà superiore è quella con il tappeto."},{personId:"A",after:["C"],nudge:"Guarda Alberto. Nella riga più in alto la sua scheda gli lascia solo due caselle. Di quale colonna ha bisogno Davide nel boudoir?",reasoning:"Alberto è nella riga 1 e nella metà sinistra. Nella casella della colonna 2 c'è un tavolo, quindi restano possibili solo la colonna 1 e la colonna 3. Davide è con Cecilia nel boudoir, e il boudoir ha solo le colonne 1 e 2. La colonna 2 è già di Cecilia, quindi a Davide serve la colonna 1. Quale casella resta allora per Alberto?",answer:"Alberto si trova in riga 1, colonna 3. La colonna 1 serve a Davide nel boudoir, e in riga 1, colonna 2 c'è un tavolo."},{personId:"E",after:["C","A"],nudge:'Guarda Enrico e Bruno. La camera da letto ha solo due colonne. Cosa significa allora "da qualche parte più a destra di Bruno" per Enrico, e in quale riga deve trovarsi Bruno?',reasoning:"Bruno è in camera da letto, nella colonna 5 o 6. Enrico si trovava da qualche parte più a destra di lui, quindi Bruno è nella colonna 5 ed Enrico nella colonna 6. La riga 1 è di Alberto e la riga 3 di Cecilia, quindi a Bruno resta solo la riga 2. Per Enrico, nella colonna 6, le righe 1, 2 e 3 sono quindi escluse, e nelle righe 4 e 5 c'è un tavolo. Dove può trovarsi ancora Enrico?",answer:"Enrico si trova in riga 6, colonna 6. Deve essere nella colonna 6; la riga 1 spetta ad Alberto, la riga 2 a Bruno, la riga 3 a Cecilia e nelle righe 4 e 5 c'è un tavolo."},{personId:"B",after:["C","A","E"],nudge:"Bruno si trovava in camera da letto. Lì cancella le righe e le colonne già occupate.",reasoning:"La camera da letto comprende le righe da 1 a 3 nelle colonne 5 e 6. La riga 1 è di Alberto, la riga 3 di Cecilia e la colonna 6 di Enrico. Quale casella resta in camera da letto?",answer:"Bruno si trova in riga 2, colonna 5. In camera da letto la riga 1, la riga 3 e la colonna 6 sono già occupate."},{personId:"V",after:["C","A","E","B"],nudge:"Ora Vito. Guarda quali righe e colonne sono ancora libere, e di quale colonna ha già bisogno Davide.",reasoning:"Sono ancora libere le righe 4 e 5 e le colonne 1 e 4. Davide è con Cecilia nel boudoir, nella colonna 1 (la colonna 2 è di Cecilia). Vito deve quindi essere nella colonna 4. Lì, nella riga 5, c'è la libreria. Quale casella resta?",answer:"Vito giace in riga 4, colonna 4. La colonna 1 spetta a Davide, e nella colonna 4 in riga 5 c'è una libreria."},{personId:"D",after:["C","A","E","B","V"],nudge:"Davide è l'ultimo. Quale riga e quale colonna sono ancora del tutto libere?",reasoning:"Restano solo una riga libera e una colonna libera. Dove si incrociano? Controlla se quella casella è compatibile con la scheda di Davide: deve trovarsi nella stessa stanza di Cecilia.",answer:"Davide si trova in riga 5, colonna 1. Sono l'unica riga e l'unica colonna libere, e la casella è nel boudoir, insieme a Cecilia."}],H="Vito giace in cucina ed Enrico è l'unico sospettato che si trova lì. Il colpevole è quindi Enrico.",J={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},K={source:T,model:x,date:M,steps:y,murderer:H,review:J},U="a6ef3e81331a",W="vertaler + keurder (claude-opus-5-5)",X="2026-10-20",Y=[{personId:"E",after:[],nudge:"Comincia da Enrico: si trovava vicino a una finestra. Quali finestre sono escluse per le schede di Alice e Cesare? Poi guarda Bernardo.",reasoning:"La riga 1 spetta ad Alice e la colonna 6 a Cesare, quindi di tutte le finestre restano solo quelle delle caselle in riga 6, colonne 1 e 3: Enrico era nella riga 6, nell'atrio. Bernardo era in un angolo della stanza, insieme a un altro uomo: Cesare o Enrico. Gli angoli del boudoir, dove era Cesare, sono tutti nella riga 1, nella riga 6 o nella colonna 6, e queste spettano ad Alice, Enrico e Cesare. Bernardo era quindi con Enrico nell'atrio, in un angolo fuori dalla riga 6 e fuori dalla colonna 4 (che spetta a Diana): riga 5, colonna 1. Quale finestra resta per Enrico, ora che la colonna 1 è di Bernardo?",answer:"Enrico si trova in riga 6, colonna 3. La riga 1 spetta ad Alice, la colonna 6 a Cesare e la colonna 1 a Bernardo, quindi resta solo la finestra della casella in riga 6, colonna 3."},{personId:"B",after:["E"],nudge:"Bernardo si trovava in un angolo della stanza, e nella sua stanza c'era anche un uomo. Quale uomo può essere: Cesare o Enrico?",reasoning:"L'altro uomo è Cesare o Enrico. Cesare era nella colonna 6, nel boudoir; gli angoli del boudoir sono nella riga 1 (che spetta ad Alice), nella riga 6 (occupata da Enrico) o nella colonna 6 (che spetta a Cesare). Bernardo era quindi con Enrico nell'atrio. L'atrio ha angoli in riga 5, colonna 1; riga 5, colonna 4; riga 6, colonna 1; e riga 6, colonna 4. La riga 6 è occupata e la colonna 4 spetta a Diana: quale angolo resta?",answer:"Bernardo si trova in riga 5, colonna 1. Doveva stare con Enrico nell'atrio, e tra gli angoli dell'atrio sono esclusi quelli della riga 6 (Enrico) e della colonna 4 (Diana)."},{personId:"C",after:["E","B"],nudge:"Cesare era nella colonna più a destra e da qualche parte più in alto di Diana. Scopri prima in quali righe della colonna 4 può trovarsi Diana.",reasoning:"Diana si trovava nella 4ª colonna. La riga 1 spetta ad Alice e le righe 5 e 6 sono occupate, quindi le restano la riga 2, la riga 3 o la riga 4. In riga 4, colonna 4 sarebbe accanto alla libreria in riga 4, colonna 3, e questo non è permesso. Diana è quindi nella riga 2 o nella riga 3. Nella colonna 6 Cesare ha ancora libere le righe 2, 3 e 4, ma deve essere da qualche parte più in alto di Diana. Quale riga va bene allora?",answer:"Cesare si trova in riga 2, colonna 6. Diana non può essere più in basso della riga 3 (la riga 4 è accanto alla libreria), la riga 1 spetta ad Alice e le righe 5 e 6 sono occupate."},{personId:"D",after:["E","B","C"],nudge:"Diana si trovava nella 4ª colonna. Quali righe sono ancora libere, e dov'è la libreria?",reasoning:"Nella colonna 4 la riga 1 spetta ad Alice e le righe 2, 5 e 6 sono occupate da Cesare, Bernardo ed Enrico. Restano le righe 3 e 4 della colonna 4. Diana non si trovava accanto a una libreria, e in riga 4, colonna 3 ce n'è una. Quale casella resta?",answer:"Diana si trova in riga 3, colonna 4. La riga 1 spetta ad Alice, le righe 2, 5 e 6 sono occupate, e la casella in riga 4, colonna 4 è accanto alla libreria in riga 4, colonna 3."},{personId:"V",after:["E","B","C","D"],nudge:"Sono ancora libere le righe 1 e 4 e le colonne 2 e 5. Quale riga spetta ad Alice?",reasoning:"La riga 1 spetta ad Alice, quindi Vanda deve essere nella riga 4. Lì sono ancora libere le colonne 2 e 5. In riga 4, colonna 2 c'è una libreria, e lì non può stare nessuno. Quale casella resta?",answer:"Vanda giace in riga 4, colonna 5. La riga 1 spetta ad Alice, e in riga 4, colonna 2 c'è una libreria."},{personId:"A",after:["E","B","C","D","V"],nudge:"Manca ancora una persona. Cosa dice la scheda di Alice?",reasoning:"Alice era nella riga più in alto, la riga 1. Tutte le colonne tranne la colonna 2 sono già occupate. Qual è la casella?",answer:"Alice si trova in riga 1, colonna 2. Era nella riga più in alto, e la colonna 2 è l'unica colonna libera."}],Z="Il colpevole è Cesare: è l'unico sospettato nel boudoir, dove è stata trovata Vanda.",aa={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ea={source:U,model:W,date:X,steps:Y,murderer:Z,review:aa},na="eee2a5a776d9",oa="vertaler + keurder (claude-opus-5-5)",ia="2026-10-20",la=[{personId:"B",after:[],nudge:"Comincia da Bruno: colonna più a destra e un angolo della stanza. Poi guarda Emilio, che si trovava in una riga più in basso di Bruno.",reasoning:"La colonna più a destra appartiene tutta alla serra. Gli angoli della serra nella colonna 6 sono nelle righe 1 e 6. Emilio si trovava in una riga più in basso di Bruno. Se Bruno fosse nella riga 6, la riga più in basso, nessuno potrebbe essere in una riga più in basso di lui. Quale angolo resta allora?",answer:"Bruno si trova in riga 1, colonna 6. Nella colonna 6 la serra ha angoli nelle righe 1 e 6, e con Bruno nella riga 6 Emilio non potrebbe essere in una riga più in basso di lui."},{personId:"C",after:["B"],nudge:"Claudio si trovava nella 4ª colonna. Guarda la riga 6: chi può ancora trovarsi lì? Pensa a Emilio e al suo letto.",reasoning:"Emilio si trovava su un letto. I letti sono nelle colonne 3 e 4, ma la colonna 4 spetta a Claudio, quindi Emilio è nella colonna 3, nella riga 3 o 4. Nella riga 6 c'è un tavolo nella colonna 1, un altro nella colonna 2 e una pianta nella colonna 5, e la colonna 6 è occupata. La colonna 3 spetta a Emilio, che non può essere nella riga 6. Chi può allora occupare la casella libera nella riga 6?",answer:"Claudio si trova in riga 6, colonna 4. Nella riga 6 restano solo le colonne 3 e 4; la colonna 3 spetta a Emilio sul letto nella riga 3 o 4, quindi la riga 6 spetta a Claudio."},{personId:"E",after:["B","C"],nudge:"Emilio era sul letto nella colonna 3, nella riga 3 o 4. Guarda la scheda di Alessio: in quale angolo può trovarsi?",reasoning:"Alessio si trovava in un angolo della stanza, e nella sua stanza c'era anche qualcuno che portava gli occhiali. Per lui sono escluse le colonne 3, 4 e 6 e le righe 1 e 6. Restano allora l'angolo in riga 2, colonna 1 in biblioteca e gli angoli nelle colonne 1 e 2 della riga 3 nella camera degli ospiti. In biblioteca nessun altro potrebbe stare con lui, perché la riga 1 è occupata e in riga 2, colonna 2 c'è una libreria. Alessio è quindi nella riga 3. Quale riga prende allora Emilio?",answer:"Emilio si trova in riga 4, colonna 3. Deve essere sul letto nella colonna 3; la riga 3 spetta ad Alessio, che solo in un angolo della camera degli ospiti nella riga 3 può avere con sé qualcuno con gli occhiali."},{personId:"V",after:["B","C","E"],nudge:"Alessio era nella riga 3 della camera degli ospiti, insieme a un'altra persona con gli occhiali. Chi è, e quale riga e quale colonna restano a Viviana?",reasoning:"Alessio era nella camera degli ospiti, nella riga 3, come si è visto prima. Anche Emilio porta gli occhiali, ma è nello studio. Quindi era Debora a trovarsi con Alessio nella camera degli ospiti. Sono ancora libere le righe 2 e 5; la camera degli ospiti comprende le righe da 3 a 6, quindi Debora prende la riga 5. Alessio e Debora prendono le colonne 1 e 2. Quale riga e quale colonna restano per Viviana?",answer:"Viviana giace in riga 2, colonna 5. Debora deve stare con Alessio nella camera degli ospiti, nella riga 5, e i due prendono le colonne 1 e 2; a Viviana restano la riga 2 e la colonna 5."},{personId:"D",after:["B","C","E","V"],nudge:"Debora era nella camera degli ospiti, nella riga 5. Cosa dice la sua scheda su Alessio?",reasoning:"Debora era con Alessio nella camera degli ospiti, nella riga 5, come si è visto prima. Lei e Alessio hanno le colonne 1 e 2. Debora si trovava da qualche parte più a sinistra di Alessio. Quale delle due colonne è a sinistra?",answer:"Debora si trova in riga 5, colonna 1. Lei e Alessio prendono le colonne 1 e 2, e Debora si trovava da qualche parte più a sinistra di Alessio."},{personId:"A",after:["B","C","E","V","D"],nudge:"Alessio è l'ultimo. Quale riga e quale colonna sono ancora libere?",reasoning:"Tutte le righe tranne la riga 3 sono occupate, e tutte le colonne tranne la colonna 2. Quella casella è un angolo della camera degli ospiti, e Debora, con i suoi occhiali, è nella stessa stanza, come chiede la scheda di Alessio.",answer:"Alessio si trova in riga 3, colonna 2. È l'unica casella libera, un angolo della camera degli ospiti, e Debora è lì con lui."}],ra="Viviana giace in serra, e Bruno è l'unico sospettato lì. Il colpevole è quindi Bruno.",sa={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ca={source:na,model:oa,date:ia,steps:la,murderer:ra,review:sa},ta="fa9cb05db2c4",da="vertaler + keurder (claude-opus-5-5)",ua="2026-10-20",ga=[{personId:"F",after:[],nudge:"Comincia da Federico e Dario: Dario si trovava esattamente due righe più in basso di Federico. In quali righe può essere Dario, se guardi anche la scheda di Alessia?",reasoning:"In riga 1, colonna 5 c'è una libreria, quindi Federico non è nella riga 1 e Dario (due righe più in basso) è almeno nella riga 4. Alessia si trovava da qualche parte più in basso di Dario e da qualche parte più in alto di un uomo, quindi Alessia non è nella riga 7 e Dario non è nella riga 6 né nella 7. Nella metà sinistra (colonne da 1 a 3) la riga 4 ha solo librerie, quindi Dario è nella riga 5. Federico era esattamente due righe più in alto: quale casella della colonna 5 è?",answer:"Federico si trova in riga 3, colonna 5. Dario deve essere nella riga 5: a sinistra la riga 4 ha solo librerie, e nella riga 6 o 7 Alessia non potrebbe essere più in basso di lui e anche più in alto di un uomo."},{personId:"C",after:["F"],nudge:"Claudio era nella 3ª colonna. Guarda quali righe sono già di altri: pensa a Dario, Alessia ed Emilio.",reasoning:"Dario è nella riga 5, come si è visto prima. Alessia si trovava da qualche parte più in basso di Dario e da qualche parte più in alto di un uomo, quindi Alessia è nella riga 6. Emilio si trovava in cantina (righe 6 e 7), quindi Emilio è nella riga 7. Nella colonna 3 ci sono un tavolo in riga 2, una libreria in riga 4 e un armadio in riga 6, e la riga 3 è occupata da Federico. Quale casella resta per Claudio?",answer:"Claudio si trova in riga 1, colonna 3. La riga 3 spetta a Federico, la 5 a Dario, la 6 ad Alessia e la 7 a Emilio; nelle righe 2, 4 e 6 della colonna 3 ci sono tavolo, libreria e armadio."},{personId:"A",after:["F","C"],nudge:"Alessia è nella riga 6. Guarda Bruna: era esattamente una colonna più a sinistra di Alessia. Quali colonne sono già assegnate?",reasoning:"Alessia è nella riga 6, come si è visto prima. Dario si trovava nella metà sinistra e la colonna 3 è occupata da Claudio; dato che Emilio si trovava in una colonna più a sinistra di Dario, la colonna 2 spetta a Dario e la colonna 1 a Emilio. Nelle colonne 3 e 5 della riga 6 ci sono degli armadi, quindi ad Alessia restano le colonne 4, 6 e 7 della riga 6. Bruna era esattamente una colonna più a sinistra di Alessia, ma la colonna 3 è occupata da Claudio e la colonna 5 da Federico. Quale casella resta allora ad Alessia?",answer:"Alessia si trova in riga 6, colonna 7. Le colonne 1 e 2 spettano a Emilio e Dario, nelle colonne 3 e 5 ci sono armadi, e con Alessia nella colonna 4 o 6 Bruna dovrebbe essere nella colonna 3 (Claudio) o 5 (Federico)."},{personId:"B",after:["F","C","A"],nudge:"Guarda la riga 4. Quali caselle sono ancora libere in quella riga, e chi può ancora trovarsi lì?",reasoning:"Bruna era esattamente una colonna più a sinistra di Alessia, quindi la colonna 6 spetta a Bruna. Nella riga 4 ci sono librerie nelle colonne da 1 a 4, la colonna 5 è occupata da Federico e la colonna 7 da Alessia. Nella riga 4 resta una sola casella, e ogni riga contiene esattamente una persona. Chi deve trovarsi lì?",answer:"Bruna si trova in riga 4, colonna 6. Per il resto la riga 4 ha solo librerie e le colonne di Federico e Alessia, e la colonna 6 spetta a Bruna."},{personId:"E",after:["F","C","A","B"],nudge:"Emilio si trovava in cantina e in una colonna più a sinistra di Dario. Quale riga e quale colonna gli restano?",reasoning:"La cantina comprende le righe 6 e 7, e la riga 6 è occupata da Alessia, quindi Emilio è nella riga 7. Dario si trovava nella metà sinistra e la colonna 3 è occupata da Claudio, quindi Dario è nella colonna 1 o 2. Emilio si trovava in una colonna più a sinistra di Dario, quindi deve essere nella colonna 1. Quale casella è?",answer:"Emilio si trova in riga 7, colonna 1. La riga 6 spetta ad Alessia, e più a sinistra di Dario (colonna 1 o 2, perché la colonna 3 è di Claudio) a Emilio resta solo la colonna 1."},{personId:"D",after:["F","C","A","B","E"],nudge:"Cosa dice la scheda di Dario? Confrontala con la posizione di Federico.",reasoning:"Dario si trovava esattamente due righe più in basso di Federico, quindi nella riga 5. Si trovava nella metà sinistra, e lì la colonna 1 è occupata da Emilio e la colonna 3 da Claudio. Quale casella resta nella riga 5?",answer:"Dario si trova in riga 5, colonna 2. Si trovava esattamente due righe più in basso di Federico, e nella metà sinistra la colonna 1 (Emilio) e la colonna 3 (Claudio) sono già occupate."},{personId:"V",after:["F","C","A","B","E","D"],nudge:"Tutti i sospettati sono sulla mappa. Quale riga e quale colonna sono ancora del tutto vuote?",reasoning:"Ogni riga e ogni colonna contiene esattamente una persona. La riga 2 e la colonna 4 sono le uniche in cui non c'è ancora nessuno. Nella casella dove si incrociano c'è un divano, e lì ci si può stare. È lì che deve trovarsi Valerio.",answer:"Valerio giace in riga 2, colonna 4. Sono l'unica riga e l'unica colonna ancora vuote."}],pa="Valerio giace nello studio. L'unico sospettato lì è Federico, quindi il colpevole è Federico.",va={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ma={source:ta,model:da,date:ua,steps:ga,murderer:pa,review:va},ba="e42c954df5cd",Ca="vertaler + keurder (claude-opus-5-5)",ha="2026-10-20",Aa=[{personId:"A",after:[],nudge:"Prima fissa le righe di Dario e Giovanni, poi guarda Barbara e Cecilia. Quali righe restano per Alice e Fabio?",reasoning:"Dario è nella riga 2 e Giovanni nella riga 3, quindi Barbara (metà superiore) deve essere nella riga 1 o 4. Cecilia si trovava in una riga più in alto di Barbara, quindi Barbara è nella riga 4 e Cecilia nella riga 1. Le righe da 1 a 4 spettano così a Cecilia, Dario, Giovanni e Barbara, quindi Alice e Fabio devono essere nelle righe da 5 a 8. Lì Alice può essere proprio accanto a un tavolo in riga 5, colonna 7 o 8, oppure in riga 6, colonna 7 (la casella in riga 7, colonna 8 non conta: un muro la separa dal tavolo). Fabio si trovava da qualche parte più in alto di Alice: in quale riga Alice non può essere?",answer:"Alice si trova in riga 6, colonna 7. Le righe da 1 a 4 spettano a Cecilia, Dario, Giovanni e Barbara; proprio accanto a un tavolo lei può essere nella riga 5 o 6, e con lei nella riga 5 Fabio non potrebbe essere da qualche parte più in alto di lei."},{personId:"C",after:["A"],nudge:"Cecilia è nella riga 1, come si è visto per Alice. Scopri prima in quale stanza è Barbara, poi leggi la scheda di Enrico.",reasoning:"Barbara è nella riga 4 e nella sua stanza c'era un'altra donna. Nel boudoir non è possibile (Cecilia è nella riga 1, Alice in cucina), quindi Barbara è in cucina, nella colonna 4 o più a destra. Enrico si trovava in una colonna più a destra di una donna: non di Cecilia, perché si trovava da qualche parte più a sinistra di lei, quindi di Barbara o di Alice. Così Enrico è nella colonna 5 o più a destra, e Cecilia ancora più a destra. In riga 1, colonna 6 c'è una libreria e la colonna 7 è occupata da Alice: quale colonna resta?",answer:"Cecilia si trova in riga 1, colonna 8. Enrico si trovava in una colonna più a destra di Barbara (cucina, colonna 4 o oltre) o di Alice, quindi nella colonna 5 o oltre, e Cecilia ancora più a destra; in riga 1, colonna 6 c'è una libreria e la colonna 7 è occupata."},{personId:"G",after:["A","C"],nudge:"Giovanni è nella riga 3, ma non era in serra. Quali caselle della riga 3 restano allora?",reasoning:"Giovanni si trovava nella 3ª riga e non era in serra, quindi non nella colonna 1, 2 o 3. Nelle colonne 5 e 6 della riga 3 c'è un tavolo, e le colonne 7 e 8 sono occupate da Alice e Cecilia. Quale casella è ancora libera?",answer:"Giovanni si trova in riga 3, colonna 4. Nella riga 3 le colonne da 1 a 3 appartengono alla serra, nelle colonne 5 e 6 della riga 3 c'è un tavolo e le colonne 7 e 8 sono occupate."},{personId:"B",after:["A","C","G"],nudge:"Barbara è in cucina nella riga 4. Guarda quali colonne sono ancora libere, e pensa a Enrico.",reasoning:"Barbara è in cucina nella riga 4, come si è visto prima. Le colonne 4 e 8 sono occupate da Giovanni e Cecilia e in riga 4, colonna 7 c'è un tavolo, quindi Barbara è nella colonna 5 o 6. Enrico era nella colonna 5 o più a destra (come si è visto per Cecilia) e da qualche parte più a sinistra di Cecilia, che è nella colonna 8; la colonna 7 è occupata, quindi Enrico è nella colonna 5 o 6. Se Barbara fosse nella colonna 6, Enrico dovrebbe essere nella colonna 5, ma allora non ci sarebbe nessuna donna più a sinistra di lui. Quale colonna prende allora Barbara?",answer:"Barbara si trova in riga 4, colonna 5. Deve essere in cucina nella colonna 5 o 6, e con lei nella colonna 6 Enrico finirebbe nella colonna 5, senza nessuna donna più a sinistra di lui."},{personId:"E",after:["A","C","G","B"],nudge:"Enrico doveva essere nella colonna 5 o 6. Ora Barbara è nella colonna 5. Quali righe sono ancora libere nella colonna 6?",reasoning:"Enrico è nella colonna 5 o 6, come si è visto prima, e la colonna 5 è occupata da Barbara. Le righe 1, 3, 4 e 6 sono già occupate da Cecilia, Giovanni, Barbara e Alice, e la riga 2 spetta a Dario. Fabio doveva essere nelle righe da 5 a 8 e da qualche parte più in alto di Alice (riga 6), quindi la riga 5 spetta a Fabio. In riga 8, colonna 6 c'è un armadio. Quale casella della colonna 6 resta per Enrico?",answer:"Enrico si trova in riga 7, colonna 6. Deve essere nella colonna 6; le righe 1, 3, 4 e 6 sono occupate, la riga 2 spetta a Dario, la riga 5 a Fabio (da qualche parte più in alto di Alice) e in riga 8, colonna 6 c'è un armadio."},{personId:"F",after:["A","C","G","B","E"],nudge:"Fabio è nella riga 5. Leggi la seconda frase della sua scheda.",reasoning:"Fabio è nella riga 5, come si è visto prima. Le colonne da 4 a 8 sono occupate, quindi restano libere le colonne 1, 2 e 3. Fabio era esattamente due colonne più a destra di un uomo. Se Fabio fosse nella colonna 1 o 2, non ci sarebbe nessuna colonna esattamente due colonne più a sinistra di lui. Quale colonna resta?",answer:"Fabio si trova in riga 5, colonna 3. Le colonne da 4 a 8 sono occupate, e con lui nella colonna 1 o 2 non potrebbe esserci un uomo due colonne più a sinistra."},{personId:"V",after:["A","C","G","B","E","F"],nudge:"Dove giace Valentino? Guarda quali righe e colonne sono ancora libere, e pensa alla scheda di Dario.",reasoning:"Sono ancora libere le righe 2 e 8, e le colonne 1 e 2. Dario si trovava nella 2ª riga, quindi Valentino è nella riga 8. In riga 8, colonna 1 c'è una pianta. In quale casella giace allora Valentino?",answer:"Valentino giace in riga 8, colonna 2. La riga 2 spetta a Dario, e in riga 8, colonna 1 c'è una pianta."},{personId:"D",after:["A","C","G","B","E","F","V"],nudge:"Cosa dice la scheda di Dario?",reasoning:"Dario si trovava nella 2ª riga. Quale colonna è ancora libera lì?",answer:"Dario si trova in riga 2, colonna 1. La riga 2 spetta a lui, e la colonna 1 è l'unica colonna libera."}],qa="Valentino giace nel boudoir, e Fabio è l'unico sospettato in quella stanza: Dario è in serra, Cecilia e Giovanni in camera da letto, Barbara e Alice in cucina ed Enrico nella camera degli ospiti. Il colpevole è quindi Fabio.",Ba={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},Da={source:ba,model:Ca,date:ha,steps:Aa,murderer:qa,review:Ba},fa="fd37cde9aa3a",Ea="vertaler + keurder (claude-opus-5-5)",La="2026-10-20",Ia=[{personId:"B",after:[],nudge:"Guarda le colonne 1 e 2: in quali stanze si trovano, e chi, secondo la propria scheda, non può proprio trovarsi lì?",reasoning:"Le colonne 1 e 2 fanno parte del boudoir e della camera da letto, e in entrambe le stanze c'è una sedia. Francesco e Diego erano in una stanza senza sedia, quindi non lì; Diego era nella stessa stanza di Camilla, quindi nemmeno Camilla. Anna si trovava da qualche parte più a destra di Camilla ed Elena esattamente quattro colonne più a destra di lei, quindi nemmeno loro due. Le colonne 1 e 2 spettano quindi a Bruno e Valeria. Bruno si trovava nella 5ª riga e non si trovava accanto a un divano: in riga 5, colonna 2 sarebbe accanto al divano nelle righe 4 e 5 della colonna 1. Chi si trova sul divano stesso non è accanto a esso. Dove si trova allora Bruno?",answer:"Bruno si trova in riga 5, colonna 1. Le colonne 1 e 2 spettano solo a Bruno e Valeria (in entrambe le stanze c'è una sedia), e in riga 5, colonna 2 Bruno sarebbe accanto a un divano."},{personId:"V",after:["B"],nudge:"Guarda la riga 7: lì deve esserci qualcuno. Prima pensa a quale colonna può avere Camilla.",reasoning:"Nelle colonne 5, 6 e 7 della riga 7 c'è un tavolo e la colonna 1 è occupata. Camilla era esattamente quattro colonne più a sinistra di Elena, quindi nella colonna 1, 2 o 3, e in una stanza senza sedia (quella di Diego): è possibile solo in cucina, nella colonna 3. Anche Diego è in cucina, e dato che la colonna 3 spetta a Camilla, la colonna 4 spetta a Diego. Le caselle nelle colonne 3 e 4 della riga 7 sono quindi escluse. La colonna 2 spetta a Valeria, come si è visto prima. Quale casella della riga 7 resta?",answer:"Valeria giace in riga 7, colonna 2. Nella riga 7 deve esserci qualcuno: la colonna 1 è occupata, nelle colonne da 5 a 7 c'è un tavolo, e le colonne 3 e 4 spettano a Camilla e Diego in cucina."},{personId:"E",after:["B","V"],nudge:"Camilla è nella colonna 3. Dov'è allora Elena, e quale uomo può trovarsi esattamente quattro righe più in basso di lei?",reasoning:"Camilla è nella colonna 3, quindi Elena è esattamente quattro colonne più a destra, nella colonna 7. Elena era esattamente quattro righe più in alto di un uomo, quindi è nella riga 1, 2 o 3. Nella riga 7 c'è Valeria, una donna, quindi la riga 3 è esclusa. Nella riga 6 non può esserci nessun uomo: Diego è in cucina, Francesco era in una stanza senza sedia, e in camera da letto c'è una sedia. Anche la riga 2 è quindi esclusa. Quale uomo è nella riga 5?",answer:"Elena si trova in riga 1, colonna 7. Deve essere nella colonna 7 (esattamente quattro colonne più a destra di Camilla) ed esattamente quattro righe più in alto di un uomo: è Bruno nella riga 5; la riga 6 non può avere un uomo e nella riga 7 c'è Valeria."},{personId:"A",after:["B","V","E"],nudge:"Guarda la colonna 6: quali caselle sono ancora libere lì, e chi può stare in quella stanza?",reasoning:"Nella colonna 6 deve esserci qualcuno. Lì ci sono un pianoforte nelle righe 2 e 3, un armadio nella riga 4 e un tavolo nella riga 7; le righe 1 e 5 sono occupate. Resta solo la casella in riga 6, colonna 6, in camera da letto, dove c'è una sedia. Camilla e Diego sono in cucina e Francesco era in una stanza senza sedia. Chi resta allora per questa casella?",answer:"Anna si trova in riga 6, colonna 6. È l'unica casella libera della colonna 6 (pianoforte, armadio e tavolo bloccano il resto), e Camilla, Diego e Francesco non possono essere in camera da letto, dove c'è una sedia."},{personId:"F",after:["B","V","E","A"],nudge:"Quale colonna resta ancora per Francesco? Poi guarda la scheda di Camilla: esattamente tre righe più in basso di lei deve esserci un uomo.",reasoning:"Le colonne 3 e 4 spettano a Camilla e Diego, come si è visto prima, quindi Francesco è nella colonna 5. Lì le righe 1, 5 e 6 sono occupate e nella riga 7 c'è un tavolo, quindi resta la riga 2, 3 o 4. Camilla si trovava esattamente tre righe più in alto di un uomo; la riga 1 è occupata e, se Camilla fosse nella riga 3, tre righe più in basso ci sarebbe Anna, quindi Camilla è nella riga 2. Diego è allora in cucina nella riga 3. Quale riga resta per Francesco?",answer:"Francesco si trova in riga 4, colonna 5. Deve essere nella colonna 5; la riga 2 spetta a Camilla (se fosse nella riga 3, Anna sarebbe tre righe più in basso di lei) e la riga 3 a Diego in cucina."},{personId:"C",after:["B","V","E","A","F"],nudge:"Camilla è nella colonna 3 della cucina. Chi c'è tre righe più in basso di ciascuna riga ancora libera per lei?",reasoning:"Camilla è in cucina nella colonna 3, quindi nella riga 1, 2 o 3. La riga 1 è occupata. Camilla si trovava esattamente tre righe più in alto di un uomo. Tre righe sotto la riga 3 c'è Anna, una donna. Chi c'è tre righe sotto la riga 2?",answer:"Camilla si trova in riga 2, colonna 3. La riga 1 è occupata e, se Camilla fosse nella riga 3, tre righe più in basso ci sarebbe Anna, una donna; tre righe sotto la riga 2 c'è Bruno."},{personId:"D",after:["B","V","E","A","F","C"],nudge:"Diego è l'ultimo. Cosa dice la sua scheda, e quale riga e quale colonna sono ancora vuote?",reasoning:"Diego era nella stessa stanza di Camilla, quindi in cucina. Tutte le altre persone sono già sulla mappa, quindi lui prende l'unica riga e l'unica colonna ancora libere. Quella casella è in cucina?",answer:"Diego si trova in riga 3, colonna 4: l'unica riga e l'unica colonna libere, e quella casella è in cucina con Camilla."}],wa="Valeria giace in camera da letto, e Anna è l'unica sospettata in quella stanza. La colpevole è quindi Anna.",Va={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},Fa={source:fa,model:Ea,date:La,steps:Ia,murderer:wa,review:Va},Qa="c895d9aa52fd",za="vertaler + keurder (claude-opus-5-5)",$a="2026-10-20",Ga=[{personId:"B",after:[],nudge:"Comincia da Barbara: si trovava esattamente tre colonne più a destra di un uomo. Quale uomo può essere? Poi guarda chi può occupare le righe 1, 2 e 8.",reasoning:"Giorgio è nella colonna 1 (esattamente due colonne più a sinistra della colonna 3 di Alberto). Barbara si trovava esattamente tre colonne più a destra di un uomo: da Alberto sarebbe la colonna 6 (di Carlo), da Carlo la colonna 9 (che non esiste), quindi da Giorgio: la colonna 4. Chi può occupare le righe 1, 2 o 8? Non Diana (riga 4). Né Alberto né Federica: Federica era esattamente una riga più in basso di Alberto, nella metà inferiore; in riga 4, colonna 3 c'è una libreria e la casella in riga 7, colonna 3 è fuori, quindi Alberto è nella riga 5 o 6 e Federica nella 6 o 7. Non Carlo: nella colonna 6 le righe 1 e 2 sono fuori e in riga 8 c'è una pianta. Non Giorgio: in riga 1, colonna 1 c'è un armadio, la riga 8 è fuori, e dalla riga 2 servirebbe un uomo nella riga 4, quella di Diana. Quelle tre righe spettano quindi a Barbara, Elisa e Vanna. In quale di queste righe Barbara, nella colonna 4, sarebbe in un angolo?",answer:"Barbara si trova in riga 1, colonna 4: esattamente tre colonne più a destra di Giorgio. Solo lei, Elisa e Vanna possono occupare le righe 1, 2 e 8; la casella in riga 2, colonna 4 non è in un angolo e quella in riga 8, colonna 4 è fuori dalla casa."},{personId:"E",after:["B"],nudge:"Le righe 1, 2 e 8 spettano a Barbara, Elisa e Vanna. Può Elisa essere nella riga più in basso, se era da qualche parte più in alto di un uomo?",reasoning:"Come si è visto per Barbara, le righe 1, 2 e 8 spettano a Barbara, Elisa e Vanna, e Barbara si trova nella riga 1. Elisa si trovava da qualche parte più in alto di un uomo, quindi non nella riga 8: è nella riga 2. La colonna 1 spetta a Giorgio, la 3 ad Alberto, la 4 è occupata da Barbara e nella riga 2 le caselle delle colonne dalla 6 alla 8 sono fuori dalla casa. La casella in riga 2, colonna 5 è nella camera degli ospiti, come Barbara, e lì Elisa non poteva essere. Quale casella resta nella riga 2?",answer:"Elisa si trova in riga 2, colonna 2. Doveva essere nella riga 2 (da qualche parte più in alto di un uomo, quindi non nella riga 8); la colonna 1 spetta a Giorgio, la 3 ad Alberto, la 4 è occupata, la casella della colonna 5 è nella stanza di Barbara e quelle delle colonne dalla 6 alla 8 sono fuori dalla casa."},{personId:"D",after:["B","E"],nudge:"Diana era nella 4ª riga e in una colonna più a sinistra di Carlo. Quali colonne sono ancora libere in quella riga?",reasoning:"Diana era nella 4ª riga. Le colonne 2 e 4 sono occupate da Elisa e Barbara, la 1 spetta a Giorgio e la 6 a Carlo. In riga 4, colonna 3 c'è una libreria e in riga 4, colonna 8 un baule. La casella in riga 4, colonna 7 è esclusa, perché Diana si trovava in una colonna più a sinistra di Carlo, che è nella colonna 6. Quale casella resta?",answer:"Diana si trova in riga 4, colonna 5. Le colonne 1, 2, 4 e 6 spettano ad altri, nella colonna 3 c'è una libreria e nella 8 un baule, e la colonna 7 non è più a sinistra di Carlo."},{personId:"V",after:["B","E","D"],nudge:"Quale riga resta per Vanna? Poi guarda le colonne 7 e 8 e Federica.",reasoning:"Le righe 1, 2 e 8 spettavano a Barbara, Elisa e Vanna, come si è visto per Barbara, quindi Vanna è nella riga 8. Le colonne 7 e 8 restano per Federica e Vanna, perché Giorgio, Alberto e Carlo hanno ciascuno la propria colonna. Nella colonna 3 Alberto può essere solo nella riga 5 o 6: in riga 4, colonna 3 c'è una libreria, la riga 7 è fuori dalla casa, e Federica doveva essere esattamente una riga più in basso, nella metà inferiore. Federica era quindi nella riga 6 o 7, e nella colonna 8 c'è un armadio sia in riga 6 sia in riga 7. La colonna 7 spetta quindi a Federica. Quale casella della riga 8 resta per Vanna?",answer:"Vanna giace in riga 8, colonna 8. La riga 8 spettava a lei, le caselle delle colonne dalla 1 alla 4 sono fuori dalla casa, la 5 è occupata da Diana, in riga 8, colonna 6 c'è una pianta e la colonna 7 spetta a Federica."},{personId:"C",after:["B","E","D","V"],nudge:"Carlo era nella 6ª colonna, in una stanza senza donne. In quali stanze della colonna 6 c'è già una donna?",reasoning:"Nella stanza di Carlo non c'era nessuna donna. Nella colonna 6 le caselle delle righe 1 e 2 sono fuori dalla casa, e in riga 8, colonna 6 c'è una pianta. La casella in riga 3, colonna 6 è nella camera degli ospiti, dove si trova Barbara. Quelle delle righe dalla 4 alla 6 sono nella serra, dove si trova Diana. Quale casella resta?",answer:"Carlo si trova in riga 7, colonna 6. Le caselle delle righe 1 e 2 sono fuori dalla casa, nella riga 8 c'è una pianta, e nella camera degli ospiti c'è Barbara e in serra Diana, entrambe donne."},{personId:"F",after:["B","E","D","V","C"],nudge:"Federica deve essere nella colonna 7, come si è visto per Vanna. Quali righe sono ancora libere lì nella metà inferiore?",reasoning:"La colonna 7 spetta a Federica, come si è visto per Vanna. Sono ancora libere le righe 3, 5 e 6; Federica si trovava nella metà inferiore, quindi nella riga 5 o 6. Se Federica fosse nella riga 5, Alberto sarebbe esattamente una riga più in alto, nella riga 4, ma quella riga è di Diana. Dove si trova Federica?",answer:"Federica si trova in riga 6, colonna 7. Nella colonna 7 sono libere solo le righe 3, 5 e 6; la riga 3 non è nella metà inferiore, e se Federica fosse nella riga 5, Alberto dovrebbe essere nella riga 4, quella di Diana."},{personId:"A",after:["B","E","D","V","C","F"],nudge:"Federica ora è sulla mappa. Cosa dice la sua scheda su Alberto?",reasoning:'Federica era esattamente una riga più in basso di Alberto, e Federica si trova nella riga 6. La scheda di Alberto dice: "Si trovava nella 3ª colonna." Dove arrivi allora?',answer:"Alberto si trova in riga 5, colonna 3. Era nella colonna 3, e Federica, che si trova nella riga 6, era esattamente una riga più in basso di lui."},{personId:"G",after:["B","E","D","V","C","F","A"],nudge:"Giorgio è l'ultimo che non è ancora sulla mappa. Cosa dice la sua scheda?",reasoning:"La riga 3 e la colonna 1 sono le uniche ancora libere. Nella casella in cui si incrociano, Giorgio è esattamente due colonne più a sinistra di Alberto ed esattamente due righe più in alto di lui, proprio come dice la sua scheda.",answer:"Giorgio si trova in riga 3, colonna 1. È all'incrocio dell'ultima riga e dell'ultima colonna libere: esattamente due colonne più a sinistra di Alberto ed esattamente due righe più in alto di lui."}],_a="Vanna giace in cantina. Federica era l'unica sospettata in cantina; Carlo è in camera da letto, Diana in serra, Alberto in cucina, e Barbara, Elisa e Giorgio nella camera degli ospiti e nello studio. La colpevole è quindi Federica.",Na={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},Sa={source:Qa,model:za,date:$a,steps:Ga,murderer:_a,review:Na},ka="e82e6e33b7b4",Pa="vertaler + keurder (claude-opus-5-5)",ja="2026-10-26",Oa=[{personId:"A",after:[],nudge:"Parti da Agnese. La sua scheda parla della riga più in basso: quali caselle di quella riga si trovano dentro la villa?",reasoning:"Agnese era nella riga più in basso, la riga 8. Nella riga 8 le caselle delle colonne da 1 a 4 e delle colonne 7 e 8 sono fuori dall'edificio. Nella riga 8, colonna 6 c'è una pianta, e lì non può trovarsi nessuno. Quale casella della riga 8 resta allora?",answer:"Agnese si trova in riga 8, colonna 5. Nella riga 8 le caselle delle colonne da 1 a 4 e da 7 a 8 sono fuori dall'edificio e nella riga 8, colonna 6 c'è una pianta."},{personId:"V",after:["A"],nudge:"Agnese è nel boudoir, e la sua scheda dice che lì c'era un'altra donna. Quale donna può essere, e dove?",reasoning:"Secondo la scheda di Agnese, nel boudoir c'era un'altra donna. Nel boudoir la colonna 5 è occupata da Agnese e nella riga 8, colonna 6 c'è una pianta; resta libera soltanto la casella in riga 7, colonna 6. Le donne sono Dora, Elena e Veronica. Dora non era nella stessa stanza di Agnese ed Elena era nella 2ª colonna. Chi deve trovarsi allora in quella casella libera?",answer:"Veronica giace in riga 7, colonna 6. È l'unica casella libera nel boudoir, e Dora (non nella stessa stanza di Agnese) ed Elena (2ª colonna) non possono trovarsi lì."},{personId:"G",after:["A","V"],nudge:"Guarda Giacomo: si trovava presso una finestra. Passa in rassegna le finestre tenendo presenti Cesare, Elena e Francesco.",reasoning:"Cesare era esattamente tre righe più in alto di Agnese, quindi la riga 5 è per Cesare; la colonna 2 è per Elena. Le caselle presso una finestra sono: riga 1, colonna 1; riga 1, colonna 2; riga 2, colonna 8; riga 5, colonna 8; riga 6, colonna 1 (nella riga 3, colonna 8 c'è una pianta e la casella in riga 8, colonna 5 è occupata da Agnese). Le caselle in riga 1, colonna 2 (Elena) e in riga 5, colonna 8 (Cesare) sono escluse. Giacomo era esattamente una riga più in alto di Francesco, e Francesco si trovava in una colonna più a sinistra di Agnese, quindi nelle colonne da 1 a 4. Se Giacomo fosse in riga 6, colonna 1, Francesco sarebbe in riga 7, ma lì c'è Veronica. Se fosse in riga 1, colonna 1, Francesco sarebbe in riga 2: nella riga 2, colonna 1 c'è una pianta, la colonna 2 è per Elena, nella riga 2, colonna 3 c'è l'armadio e la casella in riga 2, colonna 4 è accanto a quell'armadio (Francesco non si trovava accanto a un armadio). Quale casella presso una finestra resta?",answer:"Giacomo si trova in riga 2, colonna 8. Escluse: riga 1, colonna 1 (in riga 2 Francesco non può trovarsi in una colonna più a sinistra di Agnese: pianta, colonna di Elena, armadio, accanto all'armadio); riga 6, colonna 1 (la riga 7 è per Veronica); riga 1, colonna 2 (Elena); riga 5, colonna 8 (Cesare)."},{personId:"C",after:["A","V","G"],nudge:"Cesare era esattamente tre righe più in alto di Agnese. Quale riga è, e in quali colonne c'è una pianta?",reasoning:"Agnese si trova in riga 8, quindi Cesare deve trovarsi in riga 5. C'è una pianta in riga 2, colonna 1, una in riga 8, colonna 6 e una in riga 3, colonna 8. La colonna 6 è occupata da Veronica e la colonna 8 da Giacomo. Quale casella della riga 5 resta allora?",answer:"Cesare si trova in riga 5, colonna 1. È in riga 5 (esattamente tre righe più in alto di Agnese) e, tra le colonne con una pianta, la 6 (Veronica) e la 8 (Giacomo) sono già occupate."},{personId:"F",after:["A","V","G","C"],nudge:"Giacomo era esattamente una riga più in alto di Francesco, e Francesco si trovava in una colonna più a sinistra di Agnese. Quale riga e quali colonne sono?",reasoning:"Giacomo si trova in riga 2 ed era esattamente una riga più in alto di Francesco, quindi Francesco deve trovarsi in riga 3. In una colonna più a sinistra di Agnese significa nelle colonne da 1 a 4. La colonna 1 è occupata da Cesare, la colonna 2 è per Elena e nella riga 3, colonna 3 c'è un baule. Quale casella resta?",answer:"Francesco si trova in riga 3, colonna 4. È in riga 3 (Giacomo era esattamente una riga più in alto di lui) e in una colonna più a sinistra di Agnese; sono escluse la colonna 1 (Cesare), la colonna 2 (Elena) e la colonna 3 (baule)."},{personId:"E",after:["A","V","G","C","F"],nudge:"Elena era nella 2ª colonna, e nella sua stanza non c'era nessun uomo. Quali righe sono ancora libere?",reasoning:"Nella colonna 2 sono ancora libere le caselle delle righe 1, 4 e 6. La casella in riga 4, colonna 2 è in camera da letto, dove c'è Francesco (un uomo). La casella in riga 6, colonna 2 è nel corridoio, dove c'è Cesare (un uomo). Quale casella resta?",answer:"Elena si trova in riga 1, colonna 2. La riga 4 è esclusa (Francesco in camera da letto) e anche la riga 6 (Cesare nel corridoio); in sala da pranzo non c'è nessun uomo."},{personId:"B",after:["A","V","G","C","F","E"],nudge:"Bernardo era l'unico uomo nella sua stanza. Guarda quali righe e colonne sono ancora libere.",reasoning:"Sono ancora libere le righe 4 e 6 e le colonne 3 e 7. Nella riga 4, colonna 7 c'è il tavolo. La casella in riga 4, colonna 3 è in camera da letto con Francesco, e quella in riga 6, colonna 3 è nel corridoio con Cesare; lì Bernardo non sarebbe l'unico uomo. Quale casella resta?",answer:"Bernardo si trova in riga 6, colonna 7. Nella riga 4, colonna 7 c'è un tavolo, e nella riga 4, colonna 3 (Francesco) e nella riga 6, colonna 3 (Cesare) non sarebbe l'unico uomo."},{personId:"D",after:["A","V","G","C","F","E","B"],nudge:"Dora è l'ultima che non è ancora sulla mappa. Quale riga e quale colonna sono ancora libere?",reasoning:"Ogni riga e ogni colonna contiene esattamente una persona. La riga 4 e la colonna 3 sono le ultime senza nessuno. La casella in cui si incrociano, in riga 4, colonna 3, è in camera da letto, non nel boudoir di Agnese: la scheda di Dora è rispettata.",answer:"Dora si trova in riga 4, colonna 3. La riga 4 e la colonna 3 sono le ultime libere, e la casella in cui si incrociano è in camera da letto, non nella stanza di Agnese."}],Ra="Veronica giace nel boudoir, e lì Agnese è l'unica sospettata: Agnese è la colpevole. Cesare è nel corridoio, Francesco e Dora in camera da letto, Elena in sala da pranzo, Giacomo in biblioteca e Bernardo in cucina.",Ta={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-26"},xa={source:ka,model:Pa,date:ja,steps:Oa,murderer:Ra,review:Ta},Ma=Object.assign({"/.demo/puzzles/i18n/it/L1-00037ru.json":r,"/.demo/puzzles/i18n/it/L1-00037sm.json":p,"/.demo/puzzles/i18n/it/L1-00037ss.json":q,"/.demo/puzzles/i18n/it/L2-000255s.json":w,"/.demo/puzzles/i18n/it/L2-000255v.json":_,"/.demo/puzzles/i18n/it/L2-000256n.json":R,"/.demo/puzzles/i18n/it/L3-0001qi0.json":K,"/.demo/puzzles/i18n/it/L3-0002cvm.json":ea,"/.demo/puzzles/i18n/it/L3-0002cvz.json":ca,"/.demo/puzzles/i18n/it/L4-0002klf.json":ma,"/.demo/puzzles/i18n/it/L4-0002klr.json":Da,"/.demo/puzzles/i18n/it/L4-0002km3.json":Fa,"/.demo/puzzles/i18n/it/L5-0002sbj.json":Sa,"/.demo/puzzles/i18n/it/L5-005oou4.json":xa});export{Ma as default};
